function describe(node, depth) {
  if (!node) return "NOT FOUND";
  const info = { id: node.id, name: node.name, type: node.type };
  if (node.type === 'INSTANCE' || node.type === 'COMPONENT' || node.type === 'COMPONENT_SET') {
    info.componentRef = node.type;
  }
  if (node.type !== 'DOCUMENT' && node.type !== 'PAGE' && 'fills' in node) {
    info.fills = node.fills.map(f => ({
