const page = figma.getNodeById('5:2');
await figma.setCurrentPageAsync(page);

const fonts = [['Poppins','Regular'],['Poppins','Medium'],['Poppins','SemiBold'],['Poppins','Bold'],['Poppins','ExtraBold']];
const fontRes = {};
for (const [f,s] of fonts) {
  try { await figma.loadFontAsync({family:f, style:s}); fontRes[f+':'+s]='ok'; }
  catch(e) { fontRes[f+':'+s]='ERR '+e.message; }
}

const btn = figma.getNodeById('1:28');
const arr = figma.getNodeById('3:2');
const mail = figma.getNodeById('3:3');
const info = {
  btnCorner: btn.cornerRadius,
  btnRadii: [btn.topLeftRadius, btn.topRightRadius, btn.bottomRightRadius, btn.bottomLeftRadius],
  btnTextH:'', btnTextV:''
};
try { info.btnTextH = btn.children[0].textAlignHorizontal; info.btnTextV = btn.children[0].textAlignVertical; } catch(e){}
info.arrowVec = arr.children[0] ? { strokes: arr.children[0].strokes.map(s=>({color:s.color})), strokeWeight: arr.children[0].strokeWeight, fills: arr.children[0].fills.map(f=>f.type) } : null;
info.mailVecs = mail.children.map(c=>({ strokes: c.strokes.map(s=>({color:s.color})), strokeWeight: c.strokeWeight, fills: c.fills.map(f=>f.type) }));
return JSON.stringify({fontRes, info}, null, 1);
